class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  license "Apache-2.0"

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.18.0/commando_0.18.0_darwin_arm64.tar.gz"
      sha256 "824bf4026ed61fa83346bd692a8b10b7eb22a2baab1ba0efbb90df1e1a9c8640"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.18.0/commando_0.18.0_darwin_amd64.tar.gz"
      sha256 "b402ba4e1c030758ee80602271a1b8e68c7dd4eab8b25762fadf84ec1efe51ae"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.18.0/commando_0.18.0_linux_arm64.tar.gz"
      sha256 "94736bfcdbf837dbb07e628cc7a4bca9c4f32b6e51ce652004f8c48bc0910e69"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.18.0/commando_0.18.0_linux_amd64.tar.gz"
      sha256 "6810739b7e1dacbec0c3aa4621fc9ea91fdf5bcbbc3626d14f09ca30f3402496"
    end
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
    else
      bin.install "commando"
    end
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
